/* ONIT MODULE STUDIO — M2 VISUAL WORKFLOW */
(function(){
'use strict';
const MS={version:'2.2.0-m2-editable-connections',bootstrap:null,modules:[],runtime:[],users:[],editing:null,accessModule:null,activeModule:null,recordData:null,builderTab:'form',flowSelection:null,flowEdgeSelection:null,flowConnect:null};
const TYPES=[['text','Text'],['textarea','Long text'],['number','Number'],['date','Date'],['datetime','Date & time'],['email','Email'],['url','Link'],['select','Dropdown'],['checkbox','Checkbox'],['user','ONIT person']];
const PERMS=[['view','View'],['create','Create'],['edit','Edit'],['approve','Approve'],['download','Download'],['administer','Admin']];
const FLOW_TRIGGERS=[['submitted','Record submitted'],['approved','Record approved'],['updated','Record updated'],['manual','Manual button']];
const FLOW_ACTIONS=[['notify','Notify person / department'],['assign','Assign person'],['set_status','Set status'],['request_approval','Request approval'],['set_deadline','Set deadline'],['create_case','Create Case'],['send_ideas','Send to Ideas Dump'],['generate_pdf','Generate PDF'],['archive','Archive record']];
const FLOW_OPERATORS=[['equals','equals'],['not_equals','does not equal'],['contains','contains'],['greater','is greater than'],['less','is less than'],['checked','is checked'],['is_empty','is empty']];
const FLOW_MANUAL_PERMS=[['view','Anyone who can view'],['edit','Editors'],['approve','Approvers'],['administer','Module admins']];
const q=(s,r=document)=>r.querySelector(s),qa=(s,r=document)=>Array.from(r.querySelectorAll(s));
const esc=v=>typeof escapeHTML==='function'?escapeHTML(String(v??'')):String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const data=r=>r&&Object.prototype.hasOwnProperty.call(r,'data')?r.data:r;
const toast=(t,m)=>typeof showToast==='function'?showToast(t,m):alert(t+'\n'+m);
const err=e=>toast('Module Studio',String(e&&e.message||e||'Something went wrong.'));
const post=async(action,payload={})=>data(await apiPost(action,payload));
const owner=()=>typeof isOwner==='function'&&isOwner();
const fmtDate=v=>{if(!v)return'—';const d=new Date(v);return Number.isNaN(d.getTime())?String(v):d.toLocaleString();};
const typeName=t=>(TYPES.find(x=>x[0]===t)||[t,t])[1];
const moduleById=id=>MS.modules.find(m=>m.moduleId===id)||MS.runtime.find(m=>m.moduleId===id)||null;
function sectionRoot(id){return document.getElementById(id)}
function makeField(type='text'){return{fieldId:'FLD-'+(Date.now().toString(36)+Math.random().toString(36).slice(2,10)).toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,20),label:'Untitled field',type,required:false,placeholder:'',helpText:'',options:type==='select'?['Option 1','Option 2']:[]};}
function clone(v){return JSON.parse(JSON.stringify(v));}
function flowId(prefix='FLOW'){return prefix+'-'+Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,7).toUpperCase();}
function ensureWorkflow(){if(!MS.editing)return{nodes:[],edges:[]};const d=MS.editing.draft||(MS.editing.draft={fields:[]});if(!d.workflow||typeof d.workflow!=='object'||Array.isArray(d.workflow))d.workflow={nodes:[],edges:[]};if(!Array.isArray(d.workflow.nodes))d.workflow.nodes=[];if(!Array.isArray(d.workflow.edges))d.workflow.edges=[];return d.workflow;}
function makeFlowNode(kind){const wf=ensureWorkflow(),n=wf.nodes.length,x=70+(n%4)*300,y=90+Math.floor(n/4)*190,node={nodeId:flowId('NOD'),kind,x,y,config:{}};if(kind==='trigger')node.config={event:'submitted',label:'Record submitted',permission:'approve'};if(kind==='condition')node.config={fieldId:'__status',operator:'equals',value:'SUBMITTED'};if(kind==='action')node.config={action:'notify',targetMode:'user',targetUserId:'',targetDepartment:'',title:'ONIT module update',message:'A module record needs your attention.'};return node;}
function flowNode(id){return ensureWorkflow().nodes.find(n=>n.nodeId===id)||null;}
function flowActionName(a){return(FLOW_ACTIONS.find(x=>x[0]===a)||[a,a])[1];}
function flowTriggerName(a){return(FLOW_TRIGGERS.find(x=>x[0]===a)||[a,a])[1];}
function flowFieldName(id){if(id==='__status')return'Record status';const f=(MS.editing?.draft?.fields||[]).find(x=>x.fieldId===id);return f?.label||'Field';}
function flowSummary(n){if(!n)return'';const c=n.config||{};if(n.kind==='trigger')return c.event==='manual'?(c.label||'Manual action'):flowTriggerName(c.event);if(n.kind==='condition'){const op=(FLOW_OPERATORS.find(x=>x[0]===c.operator)||['',c.operator])[1];return `If ${flowFieldName(c.fieldId)} ${op}${['checked','is_empty'].includes(c.operator)?'':' '+(c.value||'…')}`;}if(n.kind==='action'){if(c.action==='notify')return c.targetMode==='department'?`Notify ${c.targetDepartment||'department'}`:`Notify ${(MS.users||[]).find(u=>u.userId===c.targetUserId)?.name||'person'}`;if(c.action==='assign')return`Assign ${(MS.users||[]).find(u=>u.userId===c.targetUserId)?.name||'person'}`;if(c.action==='set_status')return`Set status to ${c.status||'…'}`;if(c.action==='request_approval')return`Request approval from ${(MS.users||[]).find(u=>u.userId===c.targetUserId)?.name||'person'}`;if(c.action==='set_deadline')return`Set deadline +${Number(c.days||1)} day${Number(c.days||1)===1?'':'s'}`;return flowActionName(c.action);}return'';}
function flowTriggerSentence(n){const c=n?.config||{};if(c.event==='submitted')return'When a record is submitted';if(c.event==='approved')return'When a record is approved';if(c.event==='updated')return'When a record is updated';if(c.event==='manual')return`When an authorised user clicks “${c.label||'Run action'}”`;return`When ${String(flowSummary(n)||'this trigger').toLowerCase()}`;}
function flowConditionSentence(n){const c=n?.config||{},field=flowFieldName(c.fieldId),op=(FLOW_OPERATORS.find(x=>x[0]===c.operator)||['',c.operator])[1]||'matches';if(c.operator==='checked')return`if ${field} is checked`;if(c.operator==='is_empty')return`if ${field} is empty`;return`if ${field} ${op} ${c.value||'…'}`;}
function flowActionSentence(n){const c=n?.config||{},u=(MS.users||[]).find(x=>x.userId===c.targetUserId)?.name||'the selected person';if(c.action==='notify')return c.targetMode==='department'?`notify ${c.targetDepartment||'the selected department'}`:`notify ${u}`;if(c.action==='assign')return`assign the record to ${u}`;if(c.action==='set_status')return`set the status to ${c.status||'the selected status'}`;if(c.action==='request_approval')return`request approval from ${u}`;if(c.action==='set_deadline')return`set a deadline ${Number(c.days||1)} day${Number(c.days||1)===1?'':'s'} later`;if(c.action==='create_case')return'create a Case';if(c.action==='send_ideas')return'send the record to Ideas Dump';if(c.action==='generate_pdf')return'generate a PDF';if(c.action==='archive')return'archive the record';return String(flowActionName(c.action)||'run the selected action').toLowerCase();}
function flowConnectionSentence(from,to){if(!from||!to)return'';if(from.kind==='trigger'){if(to.kind==='condition')return`${flowTriggerSentence(from)}, ONIT will continue only ${flowConditionSentence(to)}.`;if(to.kind==='action')return`${flowTriggerSentence(from)}, ONIT will ${flowActionSentence(to)}.`;}if(from.kind==='condition'){if(to.kind==='action')return`If that condition is true, ONIT will ${flowActionSentence(to)}.`;if(to.kind==='condition')return`If ${flowConditionSentence(from).replace(/^if /,'')} is true, ONIT will next check whether ${flowConditionSentence(to).replace(/^if /,'')}.`;}if(from.kind==='action'){if(to.kind==='action')return`After ONIT ${flowActionSentence(from)}, it will ${flowActionSentence(to)}.`;if(to.kind==='condition')return`After ONIT ${flowActionSentence(from)}, it will continue only ${flowConditionSentence(to)}.`;}return`${flowSummary(from)} → ${flowSummary(to)}.`;}
function flowPaths(){const wf=ensureWorkflow(),out=new Map();wf.edges.forEach(e=>{if(!out.has(e.from))out.set(e.from,[]);out.get(e.from).push(e.to);});const triggers=wf.nodes.filter(n=>n.kind==='trigger'),paths=[];const walk=(ids,seen)=>{const last=ids[ids.length-1],next=(out.get(last)||[]).filter(id=>!seen.has(id));if(!next.length){paths.push(ids);return;}next.forEach(id=>{const s=new Set(seen);s.add(id);walk([...ids,id],s);});};triggers.forEach(t=>walk([t.nodeId],new Set([t.nodeId])));return paths;}
function flowPathSentence(ids){const nodes=ids.map(flowNode).filter(Boolean);if(!nodes.length||nodes[0].kind!=='trigger')return'';let sentence=flowTriggerSentence(nodes[0]),conditions=[],actions=[];nodes.slice(1).forEach(n=>{if(n.kind==='condition')conditions.push(flowConditionSentence(n).replace(/^if /,''));else if(n.kind==='action')actions.push(flowActionSentence(n));});if(conditions.length)sentence+=`, if ${conditions.join(' and ')}`;if(actions.length){sentence+=`, ONIT will `+actions.map((a,i)=>i===actions.length-1&&i>0?`and ${a}`:a).join(actions.length>2?', ':actions.length===2?' ':'');}else sentence+=', ONIT has no action connected yet';return sentence+'.';}
function flowWarnings(){const wf=ensureWorkflow(),incoming=new Set(wf.edges.map(e=>e.to)),outgoing=new Set(wf.edges.map(e=>e.from)),warnings=[];wf.nodes.forEach(n=>{if(n.kind==='trigger'&&!outgoing.has(n.nodeId))warnings.push(`${flowSummary(n)} is not connected to anything yet.`);if(n.kind!=='trigger'&&!incoming.has(n.nodeId))warnings.push(`${flowSummary(n)} will never run until it is connected from another step.`);if(n.kind==='condition'&&incoming.has(n.nodeId)&&!outgoing.has(n.nodeId))warnings.push(`${flowSummary(n)} has no next step when the condition is true.`);});wf.edges.forEach(e=>{const a=flowNode(e.from),b=flowNode(e.to);if(a?.kind==='trigger'&&a.config?.event==='submitted'&&b?.kind==='action'&&b.config?.action==='create_case')warnings.push('Every submitted record will create a Case immediately. Consider putting approval before Create Case if that is not intentional.');});return [...new Set(warnings)].slice(0,4);}
function flowNarrativeMarkup(){const wf=ensureWorkflow(),paths=flowPaths().map(flowPathSentence).filter(Boolean),warnings=flowWarnings();let focus='';if(MS.flowConnect?.from){const a=flowNode(MS.flowConnect.from),b=flowNode(MS.flowConnect.previewTo);focus=b?`<div class='ms-flow-live-preview'><b>CONNECT?</b><span>${esc(flowConnectionSentence(a,b))}</span></div>`:`<div class='ms-flow-live-preview waiting'><b>CONNECTING…</b><span>Drag onto another card and ONIT will explain the connection before you drop it.</span></div>`;}else if(MS.flowEdgeSelection){const e=wf.edges.find(x=>x.edgeId===MS.flowEdgeSelection);if(e)focus=`<div class='ms-flow-live-preview'><b>SELECTED CONNECTION</b><span>${esc(flowConnectionSentence(flowNode(e.from),flowNode(e.to)))}</span></div>`;}return `<div class='ms-flow-summary-head'><div class='ms-eyebrow'>WORKFLOW SUMMARY</div><h3>${wf.edges.length?`${wf.edges.length} connection${wf.edges.length===1?'':'s'}`:'Nothing connected yet'}</h3></div>${focus}<div class='ms-flow-summary-copy'>${paths.length?paths.map(s=>`<p>${esc(s)}</p>`).join(''):`<p>Start connecting your cards. ONIT will describe the workflow here in plain English as you build it.</p>`}</div>${warnings.length?`<div class='ms-flow-warnings'><b>CHECK THIS</b>${warnings.map(w=>`<p>⚠ ${esc(w)}</p>`).join('')}</div>`:''}`;}
function updateFlowNarrative(){const box=q('#msFlowNarrative');if(box)box.innerHTML=flowNarrativeMarkup();}


window.moduleStudioMoreCardMarkup=function(){
  if(!owner())return'';
  return `<div class='morecard' style='grid-column:1/-1'><h3>MODULE STUDIO <span class='ownerBadge'>OWNER ONLY</span></h3><div class='bigTiny'>Create new ONIT tabs, forms and internal registers without changing code. Build, preview, publish and control who can use each module.</div><div class='actions'><button class='new' onclick='openModuleStudio()'>OPEN MODULE STUDIO</button></div></div>`;
};
window.openModuleStudio=async function(){
  if(!owner()){toast('Module Studio','Only the System Owner can manage modules.');return;}
  show('moduleStudio');
  const root=q('#moduleStudioRoot');if(root)root.innerHTML=`<div class='ms-empty'>Loading Module Studio…</div>`;
  try{await loadBootstrap();renderStudioHome();}catch(e){err(e);}
};
async function loadBootstrap(){const r=await post('MODULE_STUDIO_BOOTSTRAP',{});MS.bootstrap=r;MS.modules=r.modules||[];MS.users=r.users||[];return r;}
function renderStudioHome(){
  const root=q('#moduleStudioRoot');if(!root)return;
  const mods=MS.modules||[];
  root.innerHTML=`<div class='ms-shell'>
    <div class='ms-head'><div><div class='ms-eyebrow'>SYSTEM OWNER • NO-CODE CONTROL</div><h1 class='ms-title'>Module Studio</h1><div class='ms-sub'>Build new ONIT tabs and data registers without editing code. Published modules remain isolated from Briefs, Assignments and Iterations.</div></div><div class='ms-actions'><button class='secondary' onclick='MSUI.newDepartment()'>+ DEPARTMENT</button><button class='new' onclick='MSUI.newModule()'>+ NEW MODULE</button></div></div>
    <div class='ms-grid'>
      <div class='ms-card'><div class='ms-kpi'>${mods.length}</div><p>Total modules</p></div>
      <div class='ms-card'><div class='ms-kpi'>${mods.filter(m=>m.status==='PUBLISHED').length}</div><p>Published tabs</p></div>
      <div class='ms-card'><div class='ms-kpi'>${(MS.bootstrap.departments||[]).length}</div><p>Departments available</p></div>
    </div>
    <div class='ms-grid'>${mods.length?mods.map(moduleCard).join(''):`<div class='ms-empty' style='grid-column:1/-1'><b>No custom modules yet.</b><br>Create your first module and ONIT will turn it into a real tab when you publish.</div>`}</div>
  </div>`;
}
function moduleCard(m){const cls=m.status==='PUBLISHED'?'live':m.status==='DRAFT'?'draft':'off';return `<div class='ms-card'>
  <div class='ms-meta'><span class='ms-badge ${cls}'>${esc(m.status)}</span>${m.currentVersion?`<span class='ms-badge'>V${m.currentVersion}</span>`:''}</div>
  <h3>${esc(m.name)}</h3><p>${esc(m.description||'No description yet.')}</p>
  <div class='ms-help' style='margin-top:10px'>${esc(m.departmentName||'No department')} • ${(m.draft&&m.draft.fields||m.definition&&m.definition.fields||[]).length} fields • ${((m.draft&&m.draft.workflow||m.definition&&m.definition.workflow||{}).edges||[]).length} workflow link${((m.draft&&m.draft.workflow||m.definition&&m.definition.workflow||{}).edges||[]).length===1?'':'s'}</div>
  <div class='ms-actions' style='margin-top:14px'><button class='secondary' onclick="MSUI.editModule('${esc(m.moduleId)}')">EDIT</button>${m.status==='PUBLISHED'?`<button class='secondary' onclick="MSUI.openAccess('${esc(m.moduleId)}')">ACCESS</button><button class='secondary' onclick="MSUI.openRuntime('${esc(m.moduleId)}')">OPEN TAB</button>`:''}</div>
</div>`;}

window.MSUI={
  async newDepartment(){const name=window.prompt('New department name');if(!name||!name.trim())return;try{await post('MODULE_CREATE_DEPARTMENT',{name:name.trim()});toast('Department created',name.trim());await loadBootstrap();renderStudioHome();}catch(e){err(e);}},
  newModule(){MS.builderTab='form';MS.flowSelection=null;MS.flowEdgeSelection=null;MS.editing={moduleId:'',name:'New Module',description:'',departmentId:'',departmentName:'',status:'DRAFT',currentVersion:0,draft:{name:'New Module',description:'',departmentId:'',departmentName:'',fields:[],workflow:{nodes:[],edges:[]}}};renderBuilder();},
  editModule(id){const m=MS.modules.find(x=>x.moduleId===id);if(!m)return;MS.builderTab='form';MS.flowSelection=null;MS.flowEdgeSelection=null;MS.editing=clone(m);if(!MS.editing.draft||!Array.isArray(MS.editing.draft.fields))MS.editing.draft=clone(m.definition||{name:m.name,description:m.description,departmentId:m.departmentId,departmentName:m.departmentName,fields:[],workflow:{nodes:[],edges:[]}});ensureWorkflow();renderBuilder();},
  home(){renderStudioHome();},
  builderTab(tab){syncBuilderMeta();MS.builderTab=tab==='workflow'?'workflow':'form';renderBuilder();},
  addField(type){syncBuilderMeta();MS.editing.draft.fields.push(makeField(type));renderBuilder();},
  removeField(i){syncBuilderMeta();MS.editing.draft.fields.splice(i,1);renderBuilder();},
  moveField(i,dir){syncBuilderMeta();const a=MS.editing.draft.fields,j=i+dir;if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];renderBuilder();},
  preview(){syncBuilderMeta();renderPreview();},
  async save(){try{syncBuilderMeta();await saveDraft();toast('Draft saved','Your module definition and workflow are saved.');await loadBootstrap();const fresh=MS.modules.find(x=>x.moduleId===MS.editing.moduleId);MS.editing=clone(fresh);ensureWorkflow();renderBuilder();}catch(e){err(e);}},
  async publish(){try{syncBuilderMeta();await saveDraft();const r=await post('MODULE_PUBLISH',{moduleId:MS.editing.moduleId});toast('Module published',`${MS.editing.draft.name} is now an ONIT tab • Version ${r.version}.`);await loadBootstrap();await refreshRuntime();renderStudioHome();}catch(e){err(e);}},
  async unpublish(){if(!MS.editing||!MS.editing.moduleId)return;if(!confirm('Unpublish this module? Staff will no longer see its tab. Existing records remain stored.'))return;try{await post('MODULE_UNPUBLISH',{moduleId:MS.editing.moduleId});toast('Module unpublished','The tab has been removed from staff access.');await loadBootstrap();await refreshRuntime();renderStudioHome();}catch(e){err(e);}},
  openAccess(id){openAccess(id)},openRuntime(id){openRuntime(id)},
  syncPreview(){syncBuilderMeta();renderPreview();}
};
function syncBuilderMeta(){
  if(!MS.editing)return;const d=MS.editing.draft||(MS.editing.draft={fields:[],workflow:{nodes:[],edges:[]}});ensureWorkflow();
  const name=q('#msName');if(name)d.name=name.value.trim();const desc=q('#msDescription');if(desc)d.description=desc.value.trim();const dep=q('#msDepartment');if(dep){d.departmentId=dep.value;const o=dep.selectedOptions&&dep.selectedOptions[0];d.departmentName=o?o.dataset.name||o.textContent:'';}
  qa('[data-ms-field]').forEach((row,i)=>{const f=d.fields[i];if(!f)return;f.label=q('[data-prop="label"]',row)?.value.trim()||'';f.type=q('[data-prop="type"]',row)?.value||'text';f.required=!!q('[data-prop="required"]',row)?.checked;f.placeholder=q('[data-prop="placeholder"]',row)?.value.trim()||'';f.helpText=q('[data-prop="helpText"]',row)?.value.trim()||'';const opt=q('[data-prop="options"]',row);if(opt)f.options=opt.value.split('\n').map(x=>x.trim()).filter(Boolean);});
}
async function saveDraft(){const d=MS.editing.draft;if(!d.name)throw new Error('Give the module a name.');if(!MS.editing.moduleId){const created=await post('MODULE_CREATE',{name:d.name,description:d.description,departmentId:d.departmentId,departmentName:d.departmentName});MS.editing.moduleId=created.moduleId;d.moduleId=created.moduleId;}const saved=await post('MODULE_SAVE_DRAFT',{moduleId:MS.editing.moduleId,definition:d});MS.editing.draft=clone(saved.definition);return saved;}
function renderBuilder(){
  const root=q('#moduleStudioRoot'),m=MS.editing,d=m&&m.draft;if(!root||!m)return;ensureWorkflow();
  const tab=MS.builderTab||'form';
  root.innerHTML=`<div class='ms-shell'>
    <div class='ms-head'><div><div class='ms-eyebrow'>MODULE STUDIO • ${m.moduleId?'EDIT MODULE':'NEW MODULE'}</div><h1 class='ms-title'>${esc(d.name||'New Module')}</h1><div class='ms-sub'>Build the form, then visually connect what should happen next.</div></div><div class='ms-actions'><button class='secondary' onclick='MSUI.home()'>← MODULES</button>${m.status==='PUBLISHED'?`<button class='secondary' onclick="MSUI.openAccess('${esc(m.moduleId)}')">ACCESS</button>`:''}</div></div>
    <div class='ms-builder-tabs'><button class='${tab==='form'?'active':''}' onclick="MSUI.builderTab('form')">FORM</button><button class='${tab==='workflow'?'active':''}' onclick="MSUI.builderTab('workflow')">WORKFLOW <span>${ensureWorkflow().edges.length}</span></button></div>
    <div id='msBuilderBody'></div>
    <div class='ms-savebar ms-main-savebar'><button class='secondary' onclick='MSUI.save()'>SAVE DRAFT</button>${m.status==='PUBLISHED'?`<button class='secondary ms-danger' onclick='MSUI.unpublish()'>UNPUBLISH</button>`:''}<button class='new' onclick='MSUI.publish()'>${m.status==='PUBLISHED'?'PUBLISH NEW VERSION':'PUBLISH MODULE'}</button></div>
  </div>`;
  if(tab==='workflow')renderWorkflowBuilder();else renderFormBuilder();
}
function renderFormBuilder(){const body=q('#msBuilderBody'),d=MS.editing.draft,deps=MS.bootstrap?.departments||[];if(!body)return;body.innerHTML=`<div class='ms-builder'>
  <div class='ms-panel'><h3>MODULE SETUP</h3><div class='ms-formgrid'>
    <div class='ms-field'><label>MODULE / TAB NAME</label><input id='msName' value='${esc(d.name||'')}' oninput='MSUI.syncPreview()'></div>
    <div class='ms-field'><label>DEPARTMENT</label><select id='msDepartment' onchange='MSUI.syncPreview()'><option value='' data-name=''>No department</option>${deps.map(x=>`<option value='${esc(x.departmentId)}' data-name='${esc(x.name)}' ${String(d.departmentId)===String(x.departmentId)?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div>
    <div class='ms-field full'><label>DESCRIPTION</label><textarea id='msDescription' oninput='MSUI.syncPreview()' placeholder='What is this module for?'>${esc(d.description||'')}</textarea></div>
  </div><div class='ms-divider'></div><h3>FIELDS</h3><div class='ms-help'>Add the questions or information this module needs. Field IDs are permanent once ONIT saves them.</div>
  <div class='ms-palette'>${TYPES.map(t=>`<button type='button' onclick="MSUI.addField('${t[0]}')">+ ${esc(t[1])}</button>`).join('')}</div>
  <div class='ms-fields'>${d.fields.length?d.fields.map(fieldEditor).join(''):`<div class='ms-empty'>No fields yet. Add a field above.</div>`}</div></div>
  <div class='ms-panel'><h3>LIVE PREVIEW</h3><div id='msPreview' class='ms-preview'></div></div>
</div>`;renderPreview();}

function fieldEditor(f,i){return `<div class='ms-fieldrow' data-ms-field='${i}'><div class='ms-fieldrow-head'><div class='ms-fieldrow-title'>FIELD ${i+1}${f.fieldId?` • ${esc(f.fieldId)}`:''}</div><div class='ms-mini-actions'><button onclick='MSUI.moveField(${i},-1)' title='Move up'>↑</button><button onclick='MSUI.moveField(${i},1)' title='Move down'>↓</button><button onclick='MSUI.removeField(${i})' title='Remove'>×</button></div></div><div class='ms-fieldrow-grid'>
  <div class='ms-field'><label>LABEL</label><input data-prop='label' value='${esc(f.label||'')}' oninput='MSUI.syncPreview()'></div>
  <div class='ms-field'><label>TYPE</label><select data-prop='type' onchange="MSUI.fieldType(${i},this.value)">${TYPES.map(t=>`<option value='${t[0]}' ${f.type===t[0]?'selected':''}>${esc(t[1])}</option>`).join('')}</select></div>
  <div class='ms-field'><label>PLACEHOLDER</label><input data-prop='placeholder' value='${esc(f.placeholder||'')}' oninput='MSUI.syncPreview()'></div>
  <div class='ms-field'><label>HELP TEXT</label><input data-prop='helpText' value='${esc(f.helpText||'')}' oninput='MSUI.syncPreview()'></div>
  ${f.type==='select'?`<div class='ms-field' style='grid-column:1/-1'><label>DROPDOWN OPTIONS • ONE PER LINE</label><textarea data-prop='options' oninput='MSUI.syncPreview()'>${esc((f.options||[]).join('\n'))}</textarea></div>`:''}
  <label class='ms-checkline'><input type='checkbox' data-prop='required' ${f.required?'checked':''} onchange='MSUI.syncPreview()'> Required field</label>
</div></div>`;}
function previewInput(f){const ph=esc(f.placeholder||'');if(f.type==='textarea')return`<textarea disabled placeholder='${ph}'></textarea>`;if(f.type==='select')return`<select disabled><option>${esc((f.options||[])[0]||'Choose an option')}</option></select>`;if(f.type==='checkbox')return`<label class='ms-checkline'><input type='checkbox' disabled> ${esc(f.label)}</label>`;if(f.type==='user')return`<select disabled><option>Choose ONIT person</option></select>`;const typ=f.type==='datetime'?'datetime-local':(['number','date','email','url'].includes(f.type)?f.type:'text');return`<input disabled type='${typ}' placeholder='${ph}'>`;}
function renderPreview(){const box=q('#msPreview');if(!box||!MS.editing)return;const d=MS.editing.draft;box.innerHTML=`<div class='ms-preview-card'><div class='ms-eyebrow'>${esc(d.departmentName||'ONIT MODULE')}</div><h2>${esc(d.name||'Untitled module')}</h2><p>${esc(d.description||'Add a short description for staff.')}</p>${d.fields.length?d.fields.map(f=>`<div class='ms-field'><label>${esc(f.label||'Untitled')}${f.required?' *':''}</label>${previewInput(f)}${f.helpText?`<div class='ms-help'>${esc(f.helpText)}</div>`:''}</div>`).join(''):`<div class='ms-empty'>Your fields will appear here.</div>`}</div>`;}


function renderWorkflowBuilder(){const body=q('#msBuilderBody'),wf=ensureWorkflow();if(!body)return;body.innerHTML=`<div class='ms-flow-wrap'>
  <div class='ms-flow-topbar'><div><b>VISUAL WORKFLOW</b><span>Drag cards anywhere. Select the inner step to reveal its connection dots, then drag a line to another card.</span></div><div class='ms-actions'><button class='secondary' onclick="MSFlow.add('trigger')">+ TRIGGER</button><button class='secondary' onclick="MSFlow.add('condition')">+ CONDITION</button><button class='new' onclick="MSFlow.add('action')">+ ACTION</button></div></div>
  <div class='ms-flow-layout'><div class='ms-flow-viewport' id='msFlowViewport'><div class='ms-flow-canvas' id='msFlowCanvas'>
    <svg class='ms-flow-svg' id='msFlowSvg' aria-hidden='true'><g id='msFlowEdges'></g><path id='msFlowTemp' class='ms-flow-line temp' d=''></path></svg>
    <div id='msFlowEdgeTools' class='ms-flow-edge-tools'></div>
    ${wf.nodes.map(flowCardMarkup).join('')}
    ${wf.nodes.length?'':`<div class='ms-flow-empty'><b>Start with a trigger.</b><span>Add a Trigger card, then an Action card. Select the step inside the first card and drag its dot to the next card.</span><button class='new' onclick="MSFlow.add('trigger')">+ ADD FIRST TRIGGER</button></div>`}
  </div></div><div class='ms-flow-side'><div class='ms-flow-narrative' id='msFlowNarrative'>${flowNarrativeMarkup()}</div><div class='ms-flow-inspector' id='msFlowInspector'>${flowInspectorMarkup()}</div></div></div>
  <div class='ms-flow-legend'><span><i class='trigger'></i> Trigger</span><span><i class='condition'></i> Condition</span><span><i class='action'></i> Action</span><span class='ms-help'>Connected = automatic. A Trigger set to “Manual button” appears as a button on each record.</span></div>
</div>`;requestAnimationFrame(()=>{wireFlowCards();drawFlowEdges();});}
function flowCardMarkup(n){const sel=MS.flowSelection===n.nodeId?' selected':'';const label=n.kind==='trigger'?'TRIGGER':n.kind==='condition'?'CONDITION':'ACTION';return `<div class='ms-flow-card ${n.kind}${sel}' data-flow-node='${esc(n.nodeId)}' style='left:${Number(n.x)||40}px;top:${Number(n.y)||40}px'>
  <div class='ms-flow-card-head' data-flow-drag='${esc(n.nodeId)}'><span class='ms-flow-kind'>${label}</span><button type='button' onclick="event.stopPropagation();MSFlow.remove('${esc(n.nodeId)}')">×</button></div>
  <div class='ms-flow-card-body'><div class='ms-flow-element ${sel?'selected':''}' data-flow-select='${esc(n.nodeId)}'>
    <span class='ms-flow-port in' data-flow-in='${esc(n.nodeId)}' title='Connect into this step'></span><span class='ms-flow-step-text'>${esc(flowSummary(n))}</span><span class='ms-flow-port out' data-flow-out='${esc(n.nodeId)}' title='Drag to connect'></span>
  </div><div class='ms-flow-card-note'>${esc(flowCardNote(n))}</div></div></div>`;}
function flowCardNote(n){const c=n.config||{};if(n.kind==='trigger')return c.event==='manual'?'Shows as a record button':'Starts automatically';if(n.kind==='condition')return'Only continues when true';if(n.kind==='action'&&c.action==='create_case')return'Uses existing Cases permission';if(n.kind==='action'&&c.action==='send_ideas')return'Uses existing Ideas Dump permission';return'Runs when reached';}
function flowInspectorMarkup(){const wf=ensureWorkflow();if(MS.flowEdgeSelection){const e=wf.edges.find(x=>x.edgeId===MS.flowEdgeSelection);if(e){const a=flowNode(e.from),b=flowNode(e.to);return `<div class='ms-flow-inspector-head'><div><div class='ms-eyebrow'>CONNECTION</div><h3>${esc(flowSummary(a))} → ${esc(flowSummary(b))}</h3></div></div><div class='ms-owner-note'><b>This connection means:</b><br>${esc(flowConnectionSentence(a,b))}</div><button class='secondary ms-danger' onclick="MSFlow.removeEdge('${esc(e.edgeId)}')">DELETE CONNECTION</button>`;}}
  const n=flowNode(MS.flowSelection);if(!n)return `<div class='ms-flow-inspector-head'><div><div class='ms-eyebrow'>WORKFLOW HELP</div><h3>Select a card</h3></div></div><p>Click the step inside a card to edit it and reveal the connector dots.</p><div class='ms-owner-note'><b>How to connect:</b><br>1. Select a step.<br>2. Drag from its right dot.<br>3. Drop on the left dot of another step.</div>`;
  if(n.kind==='trigger')return triggerInspector(n);if(n.kind==='condition')return conditionInspector(n);return actionInspector(n);}
function flowFieldOptions(includeStatus=true,filterType=''){let arr=(MS.editing?.draft?.fields||[]).filter(f=>!filterType||f.type===filterType);return `${includeStatus?`<option value='__status'>Record status</option>`:''}${arr.map(f=>`<option value='${esc(f.fieldId)}'>${esc(f.label)}</option>`).join('')}`;}
function flowUserOptions(selected){return `<option value=''>Choose person…</option>${(MS.users||[]).map(u=>`<option value='${esc(u.userId)}' ${String(selected||'')===String(u.userId)?'selected':''}>${esc(u.name)}${u.department?' • '+esc(u.department):''}</option>`).join('')}`;}
function flowDepartmentOptions(selected){const deps=MS.bootstrap?.departments||[];return `<option value=''>Choose department…</option>${deps.map(d=>`<option value='${esc(d.name)}' ${String(selected||'')===String(d.name)?'selected':''}>${esc(d.name)}</option>`).join('')}`;}
function inspectorSelect(label,key,value,options){return `<div class='ms-field'><label>${label}</label><select onchange="MSFlow.update('${esc(key)}',this.value)">${options.map(o=>`<option value='${esc(o[0])}' ${String(value)===String(o[0])?'selected':''}>${esc(o[1])}</option>`).join('')}</select></div>`;}
function triggerInspector(n){const c=n.config||{};return `<div class='ms-flow-inspector-head'><div><div class='ms-eyebrow'>TRIGGER</div><h3>${esc(flowSummary(n))}</h3></div></div>${inspectorSelect('WHEN','event',c.event||'submitted',FLOW_TRIGGERS)}${c.event==='manual'?`<div class='ms-field'><label>BUTTON LABEL</label><input value='${esc(c.label||'Run action')}' onchange="MSFlow.update('label',this.value)"></div>${inspectorSelect('WHO CAN USE IT','permission',c.permission||'approve',FLOW_MANUAL_PERMS)}`:''}<div class='ms-owner-note'>${c.event==='manual'?'This becomes a button on each record. It only runs when an authorised user clicks it.':'This starts automatically when the record event happens.'}</div>`;}
function conditionInspector(n){const c=n.config||{};const fields=[['__status','Record status'],...(MS.editing?.draft?.fields||[]).map(f=>[f.fieldId,f.label])];return `<div class='ms-flow-inspector-head'><div><div class='ms-eyebrow'>CONDITION</div><h3>${esc(flowSummary(n))}</h3></div></div>${inspectorSelect('FIELD','fieldId',c.fieldId||'__status',fields)}${inspectorSelect('RULE','operator',c.operator||'equals',FLOW_OPERATORS)}${['checked','is_empty'].includes(c.operator)?'':`<div class='ms-field'><label>VALUE</label><input value='${esc(c.value||'')}' onchange="MSFlow.update('value',this.value)"></div>`}<div class='ms-owner-note'>If this is false, ONIT stops this branch of the workflow.</div>`;}
function actionInspector(n){const c=n.config||{},action=c.action||'notify';let extra='';
  if(action==='notify'){extra=`${inspectorSelect('SEND TO','targetMode',c.targetMode||'user',[['user','Person'],['department','Department']])}${c.targetMode==='department'?`<div class='ms-field'><label>DEPARTMENT</label><select onchange="MSFlow.update('targetDepartment',this.value)">${flowDepartmentOptions(c.targetDepartment)}</select></div>`:`<div class='ms-field'><label>PERSON</label><select onchange="MSFlow.update('targetUserId',this.value)">${flowUserOptions(c.targetUserId)}</select></div>`}<div class='ms-field'><label>NOTIFICATION TITLE</label><input value='${esc(c.title||'ONIT module update')}' onchange="MSFlow.update('title',this.value)"></div><div class='ms-field'><label>MESSAGE</label><textarea onchange="MSFlow.update('message',this.value)">${esc(c.message||'A module record needs your attention.')}</textarea></div>`;}
  if(action==='assign')extra=`<div class='ms-field'><label>ASSIGN TO</label><select onchange="MSFlow.update('targetUserId',this.value)">${flowUserOptions(c.targetUserId)}</select></div>`;
  if(action==='set_status')extra=`<div class='ms-field'><label>STATUS</label><input value='${esc(c.status||'IN REVIEW')}' onchange="MSFlow.update('status',this.value)"></div>`;
  if(action==='request_approval')extra=`<div class='ms-field'><label>APPROVER</label><select onchange="MSFlow.update('targetUserId',this.value)">${flowUserOptions(c.targetUserId)}</select></div>`;
  if(action==='set_deadline')extra=`<div class='ms-field'><label>DAYS FROM TRIGGER</label><input type='number' min='0' max='365' value='${esc(c.days??1)}' onchange="MSFlow.update('days',this.value)"></div>`;
  if(action==='create_case')extra=flowMappingInspector(c,[['titleFieldId','CASE TITLE',''],['descriptionFieldId','DESCRIPTION',''],['brandFieldId','BRAND / CLIENT',''],['sourceUrlFieldId','SOURCE LINK','url']]);
  if(action==='send_ideas')extra=flowMappingInspector(c,[['observationFieldId','OBSERVATION / HEADLINE',''],['whyFieldId','WHY IT MATTERS',''],['brandFieldId','BRAND',''],['sourceUrlFieldId','SOURCE LINK','url'],['tagsFieldId','TAGS','']]);
  return `<div class='ms-flow-inspector-head'><div><div class='ms-eyebrow'>ACTION</div><h3>${esc(flowSummary(n))}</h3></div></div>${inspectorSelect('DO THIS','action',action,FLOW_ACTIONS)}${extra}<div class='ms-owner-note'>${action==='create_case'?'The person running this step must already have Cases access.':action==='send_ideas'?'The person running this step must already have Ideas Dump access.':'ONIT will run this only when the workflow reaches this card.'}</div>`;}
function flowMappingInspector(c,rows){return `<div class='ms-flow-map'>${rows.map(r=>`<div class='ms-field'><label>${r[1]}</label><select onchange="MSFlow.update('${r[0]}',this.value)"><option value=''>ONIT chooses / leave blank</option>${(MS.editing?.draft?.fields||[]).filter(f=>!r[2]||f.type===r[2]).map(f=>`<option value='${esc(f.fieldId)}' ${String(c[r[0]]||'')===String(f.fieldId)?'selected':''}>${esc(f.label)}</option>`).join('')}</select></div>`).join('')}</div>`;}
function wireFlowCards(){qa('[data-flow-select]').forEach(el=>el.addEventListener('click',e=>{if(e.target.closest('.ms-flow-port'))return;MS.flowSelection=el.dataset.flowSelect;MS.flowEdgeSelection=null;renderWorkflowBuilder();}));qa('[data-flow-drag]').forEach(h=>h.addEventListener('pointerdown',startCardDrag));qa('[data-flow-out]').forEach(p=>p.addEventListener('pointerdown',startConnector));}
function startCardDrag(e){if(e.target.closest('button,input,select,textarea'))return;const id=e.currentTarget.dataset.flowDrag,n=flowNode(id),card=q(`[data-flow-node="${CSS.escape(id)}"]`),canvas=q('#msFlowCanvas');if(!n||!card||!canvas)return;e.preventDefault();MS.flowSelection=id;MS.flowEdgeSelection=null;const sx=e.clientX,sy=e.clientY,ox=Number(n.x)||0,oy=Number(n.y)||0;const move=ev=>{const cr=canvas.getBoundingClientRect(),nx=Math.max(15,Math.min(cr.width-card.offsetWidth-15,ox+ev.clientX-sx)),ny=Math.max(15,Math.min(cr.height-card.offsetHeight-15,oy+ev.clientY-sy));n.x=Math.round(nx);n.y=Math.round(ny);card.style.left=n.x+'px';card.style.top=n.y+'px';drawFlowEdges();};const up=()=>{document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',up);q('#msFlowInspector').innerHTML=flowInspectorMarkup();};document.addEventListener('pointermove',move);document.addEventListener('pointerup',up,{once:true});}
function startConnector(e){const from=e.currentTarget.dataset.flowOut;if(!from)return;e.stopPropagation();e.preventDefault();MS.flowSelection=from;MS.flowEdgeSelection=null;MS.flowConnect={from,x:e.clientX,y:e.clientY,previewTo:''};updateFlowNarrative();const move=ev=>{if(!MS.flowConnect)return;MS.flowConnect.x=ev.clientX;MS.flowConnect.y=ev.clientY;const target=document.elementFromPoint(ev.clientX,ev.clientY)?.closest?.('[data-flow-in]'),to=target?.dataset?.flowIn||'';if(MS.flowConnect.previewTo!==to){MS.flowConnect.previewTo=to;updateFlowNarrative();}drawFlowEdges();};const up=ev=>{const target=document.elementFromPoint(ev.clientX,ev.clientY)?.closest?.('[data-flow-in]'),to=target?.dataset?.flowIn;document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',up);const src=MS.flowConnect?.from;MS.flowConnect=null;if(src&&to&&src!==to){const wf=ensureWorkflow();if(!wf.edges.some(x=>x.from===src&&x.to===to))wf.edges.push({edgeId:flowId('EDG'),from:src,to});}renderWorkflowBuilder();};document.addEventListener('pointermove',move);document.addEventListener('pointerup',up,{once:true});}
function pathBetween(a,b){const dx=Math.max(70,Math.abs(b.x-a.x)*.48),c1=a.x+dx,c2=b.x-dx;return`M ${a.x} ${a.y} C ${c1} ${a.y}, ${c2} ${b.y}, ${b.x} ${b.y}`;}
function portPoint(id,dir){const canvas=q('#msFlowCanvas'),el=q(`[data-flow-${dir}="${CSS.escape(id)}"]`);if(!canvas||!el)return null;const cr=canvas.getBoundingClientRect(),r=el.getBoundingClientRect();return{x:r.left-cr.left+r.width/2,y:r.top-cr.top+r.height/2};}
function drawFlowEdges(){const g=q('#msFlowEdges'),temp=q('#msFlowTemp'),canvas=q('#msFlowCanvas'),tools=q('#msFlowEdgeTools');if(!g||!canvas)return;g.innerHTML=ensureWorkflow().edges.map(e=>{const a=portPoint(e.from,'out'),b=portPoint(e.to,'in');if(!a||!b)return'';const sel=MS.flowEdgeSelection===e.edgeId?' selected':'';return`<path class='ms-flow-hit' data-flow-edge='${esc(e.edgeId)}' d='${pathBetween(a,b)}'></path><path class='ms-flow-line${sel}' data-flow-edge-visible='${esc(e.edgeId)}' d='${pathBetween(a,b)}'></path>`;}).join('');qa('[data-flow-edge]',g).forEach(p=>p.addEventListener('click',e=>{e.stopPropagation();MS.flowEdgeSelection=p.dataset.flowEdge;MS.flowSelection=null;q('#msFlowInspector').innerHTML=flowInspectorMarkup();updateFlowNarrative();drawFlowEdges();}));if(tools){const e=ensureWorkflow().edges.find(x=>x.edgeId===MS.flowEdgeSelection),a=e&&portPoint(e.from,'out'),b=e&&portPoint(e.to,'in');tools.innerHTML=e&&a&&b?`<button type='button' class='ms-flow-edge-delete' style='left:${Math.round((a.x+b.x)/2)}px;top:${Math.round((a.y+b.y)/2)}px' onclick="event.stopPropagation();MSFlow.removeEdge('${esc(e.edgeId)}')" title='Delete connection'>× <span>Delete link</span></button>`:'';}if(temp){if(MS.flowConnect){const a=portPoint(MS.flowConnect.from,'out'),cr=canvas.getBoundingClientRect(),b={x:MS.flowConnect.x-cr.left,y:MS.flowConnect.y-cr.top};temp.setAttribute('d',a?pathBetween(a,b):'');}else temp.setAttribute('d','');}}
window.MSFlow={
  add(kind){const wf=ensureWorkflow(),n=makeFlowNode(kind);wf.nodes.push(n);MS.flowSelection=n.nodeId;MS.flowEdgeSelection=null;renderWorkflowBuilder();},
  remove(id){const wf=ensureWorkflow();wf.nodes=wf.nodes.filter(n=>n.nodeId!==id);wf.edges=wf.edges.filter(e=>e.from!==id&&e.to!==id);if(MS.flowSelection===id)MS.flowSelection=null;renderWorkflowBuilder();},
  removeEdge(id){const wf=ensureWorkflow();wf.edges=wf.edges.filter(e=>e.edgeId!==id);MS.flowEdgeSelection=null;renderWorkflowBuilder();},
  update(key,value){const n=flowNode(MS.flowSelection);if(!n)return;n.config=n.config||{};n.config[key]=value;if(n.kind==='action'&&key==='action'){const a=value;n.config={action:a};if(a==='notify')Object.assign(n.config,{targetMode:'user',targetUserId:'',title:'ONIT module update',message:'A module record needs your attention.'});if(a==='set_status')n.config.status='IN REVIEW';if(a==='set_deadline')n.config.days=1;}if(n.kind==='trigger'&&key==='event'&&value==='manual'){n.config.label=n.config.label||'Run action';n.config.permission=n.config.permission||'approve';}renderWorkflowBuilder();}
};
document.addEventListener('keydown',e=>{if(!MS.flowEdgeSelection)return;const t=e.target;if(t&&((t.tagName&&['INPUT','TEXTAREA','SELECT'].includes(t.tagName))||t.isContentEditable))return;if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();MSFlow.removeEdge(MS.flowEdgeSelection);}});

async function openAccess(id){
  show('moduleStudio');const root=q('#moduleStudioRoot');if(root)root.innerHTML=`<div class='ms-empty'>Loading access…</div>`;
  try{const r=await post('MODULE_ACCESS_LIST',{moduleId:id});MS.accessModule=id;renderAccess(r);}catch(e){err(e);}
}
function renderAccess(r){const root=q('#moduleStudioRoot'),m=moduleById(r.moduleId);if(!root)return;root.innerHTML=`<div class='ms-shell'><div class='ms-head'><div><div class='ms-eyebrow'>MODULE STUDIO • ACCESS</div><h1 class='ms-title'>${esc(m?.name||'Module')}</h1><div class='ms-sub'>Nothing is granted automatically. The System Owner decides exactly what each staff member can do.</div></div><div class='ms-actions'><button class='secondary' onclick='MSUI.home()'>← MODULES</button><button class='secondary' onclick="MSUI.editModule('${esc(r.moduleId)}')">EDIT MODULE</button></div></div><div class='ms-owner-note'><b>System Owner:</b> full access is permanent and does not need a grant.</div><div class='ms-access-list'>${(r.users||[]).filter(u=>u.userId!==r.ownerUserId).map(accessRow).join('')||`<div class='ms-empty'>No active staff accounts found.</div>`}</div></div>`;}
function accessRow(u){return `<div class='ms-access-row' data-access-user='${esc(u.userId)}'><div class='person'><b>${esc(u.name)}</b><small>${esc(u.department||'No department')} • ${esc(u.position||'')}</small></div>${PERMS.map(p=>`<label class='ms-access-cell'>${esc(p[1])}<input type='checkbox' data-perm='${p[0]}' ${u.permissions&&u.permissions[p[0]]?'checked':''}></label>`).join('')}<button class='secondary' onclick="MSAccess.save('${esc(u.userId)}')">SAVE</button></div>`;}
window.MSAccess={async save(userId){const row=qa('[data-access-user]').find(x=>x.dataset.accessUser===userId);if(!row)return;const permissions={};qa('[data-perm]',row).forEach(x=>permissions[x.dataset.perm]=x.checked);try{const r=await post('MODULE_SET_ACCESS',{moduleId:MS.accessModule,targetUserId:userId,permissions});qa('[data-perm]',row).forEach(x=>x.checked=!!r.permissions[x.dataset.perm]);toast('Access updated','The module permission has been saved.');await refreshRuntime();}catch(e){err(e);}}};
async function refreshRuntime(){
  if(typeof currentUser==='undefined'||!currentUser)return;
  try{const r=await post('MODULE_RUNTIME_LIST',{});MS.runtime=r.modules||[];MS.users=r.users||[];renderRuntimeNavigation();}catch(e){console.warn('Module Studio runtime list unavailable',e);}
}
window.openModuleRuntime=openRuntime;
async function openRuntime(id){
  show('moduleRuntime');MS.activeModule=id;const root=q('#moduleRuntimeRoot');if(root)root.innerHTML=`<div class='ms-empty'>Loading module…</div>`;
  try{const r=await post('MODULE_RECORDS',{moduleId:id});MS.recordData=r;renderRuntime(r);}catch(e){err(e);if(root)root.innerHTML=`<div class='ms-empty'>${esc(e&&e.message||e)}</div>`;}
}
function renderRuntime(r){
  const root=q('#moduleRuntimeRoot'),m=r.module,def=r.definition||m.definition||{fields:[]},p=r.permissions||m.permissions||{};if(!root)return;
  root.innerHTML=`<div class='ms-shell'><div class='ms-runtime-head'><div><div class='ms-eyebrow'>${esc(m.departmentName||'ONIT MODULE')}</div><h1 class='ms-title'>${esc(m.name)}</h1><div class='ms-sub'>${esc(m.description||'')}</div></div><div class='ms-actions'>${p.create?`<button class='new' onclick='MSRuntime.newRecord()'>+ NEW RECORD</button>`:''}${owner()?`<button class='secondary' onclick="openModuleStudio();setTimeout(()=>MSUI.openAccess('${esc(m.moduleId)}'),0)">MANAGE ACCESS</button>`:''}</div></div><div id='msRuntimeComposer'></div><div class='ms-panel'><div class='ms-head'><div><h3>RECORDS</h3><div class='ms-help'>${(r.records||[]).length} active record${(r.records||[]).length===1?'':'s'} • Definition v${m.currentVersion||0}</div></div></div><div class='ms-records'>${(r.records||[]).length?(r.records||[]).map(x=>recordCard(x,def,p,r.users||[])).join(''):`<div class='ms-empty'>No records yet.${p.create?' Create the first one above.':''}</div>`}</div></div></div>`;
}
function displayValue(f,v,users){if(f.type==='checkbox')return v?'Yes':'No';if(f.type==='user'){const u=(users||[]).find(x=>x.userId===v);return u?u.name:(v||'—');}if(f.type==='date')return v||'—';if(f.type==='datetime'){if(!v)return'—';const d=new Date(v);return Number.isNaN(d.getTime())?String(v):d.toLocaleString();}return v===''||v==null?'—':String(v);}
function manualFlowButtons(def,p,rec){const wf=def.workflow||{},nodes=wf.nodes||[],edges=wf.edges||[];return nodes.filter(n=>n.kind==='trigger'&&n.config&&n.config.event==='manual'&&edges.some(e=>e.from===n.nodeId)).filter(n=>!!p[n.config.permission||'approve']).map(n=>`<button class='secondary' onclick="MSRuntime.runWorkflow('${esc(rec.recordId)}','${esc(n.nodeId)}')">${esc(n.config.label||'RUN ACTION')}</button>`).join('');}
function recordCard(rec,def,p,users){const meta=[rec.assignedToName?`Assigned: ${esc(rec.assignedToName)}`:'',rec.workflowDeadline?`Deadline: ${esc(fmtDate(rec.workflowDeadline))}`:'',rec.linkedCaseId?`Case: ${esc(rec.linkedCaseId)}`:'',rec.linkedIdeaSignalId?`Idea: ${esc(rec.linkedIdeaSignalId)}`:''].filter(Boolean).join(' • ');return `<div class='ms-record'><div class='ms-record-top'><div><span class='ms-badge ${rec.status==='APPROVED'?'live':'draft'}'>${esc(rec.status)}</span><div class='ms-help' style='margin-top:6px'>Created by ${esc(rec.createdByName||'ONIT user')} • ${esc(fmtDate(rec.createdAt))}</div>${meta?`<div class='ms-help' style='margin-top:5px'>${meta}</div>`:''}</div><div class='ms-actions'>${manualFlowButtons(def,p,rec)}${p.edit?`<button class='secondary' onclick="MSRuntime.editRecord('${esc(rec.recordId)}')">EDIT</button>`:''}${p.approve&&rec.status!=='APPROVED'?`<button class='secondary' onclick="MSRuntime.approve('${esc(rec.recordId)}')">APPROVE</button>`:''}${p.administer?`<button class='secondary ms-danger' onclick="MSRuntime.archive('${esc(rec.recordId)}')">ARCHIVE</button>`:''}</div></div><div class='ms-record-grid'>${(def.fields||[]).map(f=>`<div class='ms-value'><small>${esc(f.label)}</small><div>${esc(displayValue(f,rec.data&&rec.data[f.fieldId],users))}</div></div>`).join('')}</div>${p.download&&rec.generatedPdfUrl?`<div class='ms-help' style='margin-top:10px'><a href='${esc(rec.generatedPdfUrl)}' target='_blank' rel='noopener'>Open generated PDF</a></div>`:''}${rec.approvedByName?`<div class='ms-help' style='margin-top:10px'>Approved by ${esc(rec.approvedByName)} • ${esc(fmtDate(rec.approvedAt))}</div>`:''}</div>`;}
function recordInput(f,value,users){const id=`msrec_${esc(f.fieldId)}`,v=value??'';if(f.type==='textarea')return`<textarea id='${id}' data-field-id='${esc(f.fieldId)}' placeholder='${esc(f.placeholder||'')}'>${esc(v)}</textarea>`;if(f.type==='select')return`<select id='${id}' data-field-id='${esc(f.fieldId)}'><option value=''>Choose…</option>${(f.options||[]).map(o=>`<option value='${esc(o)}' ${String(v)===String(o)?'selected':''}>${esc(o)}</option>`).join('')}</select>`;if(f.type==='checkbox')return`<label class='ms-checkline'><input id='${id}' data-field-id='${esc(f.fieldId)}' data-field-type='checkbox' type='checkbox' ${v?'checked':''}> Yes</label>`;if(f.type==='user')return`<select id='${id}' data-field-id='${esc(f.fieldId)}'><option value=''>Choose ONIT person…</option>${(users||[]).map(u=>`<option value='${esc(u.userId)}' ${String(v)===String(u.userId)?'selected':''}>${esc(u.name)}${u.department?' • '+esc(u.department):''}</option>`).join('')}</select>`;const typ=f.type==='datetime'?'datetime-local':(['number','date','email','url'].includes(f.type)?f.type:'text');let shown=v;if(f.type==='datetime'&&v){const d=new Date(v);if(!Number.isNaN(d.getTime()))shown=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}return`<input id='${id}' data-field-id='${esc(f.fieldId)}' type='${typ}' value='${esc(shown)}' placeholder='${esc(f.placeholder||'')}'>`;}
function showRecordForm(rec){const r=MS.recordData;if(!r)return;const def=r.definition||r.module.definition||{fields:[]},box=q('#msRuntimeComposer'),values=rec&&rec.data||{};if(!box)return;box.innerHTML=`<div class='ms-panel'><div class='ms-head'><div><h3>${rec?'EDIT RECORD':'NEW RECORD'}</h3><div class='ms-help'>${esc(r.module.name)}</div></div><button class='secondary' onclick='MSRuntime.cancelForm()'>CANCEL</button></div><div class='ms-runtime-form'>${(def.fields||[]).map(f=>`<div class='ms-field ${f.type==='textarea'?'full':''}'><label>${esc(f.label)}${f.required?' *':''}</label>${recordInput(f,values[f.fieldId],r.users||[])}${f.helpText?`<div class='ms-help'>${esc(f.helpText)}</div>`:''}</div>`).join('')}</div><div class='ms-actions' style='margin-top:14px'><button class='new' onclick="MSRuntime.saveRecord('${rec?esc(rec.recordId):''}')">${rec?'SAVE CHANGES':'CREATE RECORD'}</button></div></div>`;box.scrollIntoView({behavior:'smooth',block:'start'});}
window.MSRuntime={
  newRecord(){showRecordForm(null);},editRecord(id){const rec=MS.recordData?.records?.find(x=>x.recordId===id);if(rec)showRecordForm(rec);},cancelForm(){const b=q('#msRuntimeComposer');if(b)b.innerHTML='';},
  async saveRecord(recordId){try{const payload={};qa('#msRuntimeComposer [data-field-id]').forEach(el=>{payload[el.dataset.fieldId]=el.dataset.fieldType==='checkbox'?el.checked:el.value;});if(recordId)await post('MODULE_RECORD_UPDATE',{moduleId:MS.activeModule,recordId,record:payload});else await post('MODULE_RECORD_CREATE',{moduleId:MS.activeModule,record:payload});toast(recordId?'Record updated':'Record created','ONIT saved the module record.');await openRuntime(MS.activeModule);}catch(e){err(e);}},
  async approve(id){try{const r=await post('MODULE_RECORD_APPROVE',{moduleId:MS.activeModule,recordId:id});toast('Record approved',r.workflow&&r.workflow.errors&&r.workflow.errors.length?'Approval saved. One workflow action needs attention.':'Approval saved.');await openRuntime(MS.activeModule);}catch(e){err(e);}},
  async runWorkflow(id,triggerNodeId){try{const r=await post('MODULE_WORKFLOW_RUN_MANUAL',{moduleId:MS.activeModule,recordId:id,triggerNodeId});const count=(r.results||[]).filter(x=>x.ok).length,errors=(r.errors||[]).length;toast('Workflow complete',`${count} action${count===1?'':'s'} completed${errors?` • ${errors} needs attention`:''}.`);await openRuntime(MS.activeModule);}catch(e){err(e);}},
  async archive(id){if(!confirm('Archive this record?'))return;try{await post('MODULE_RECORD_ARCHIVE',{moduleId:MS.activeModule,recordId:id});toast('Record archived','It has been removed from the active list.');await openRuntime(MS.activeModule);}catch(e){err(e);}}
};
function renderRuntimeNavigation(){
  qa('.ms-module-nav').forEach(n=>n.remove());qa('.ms-mobile-module').forEach(n=>n.remove());
  const more=q('#navMore'),nav=more&&more.parentElement;
  (MS.runtime||[]).forEach(m=>{if(nav&&more){const b=document.createElement('button');b.className='ms-module-nav mobileSecondaryNav';b.dataset.moduleId=m.moduleId;b.type='button';b.innerHTML=`<span class='navIcon'>M</span><span class='navLabel'>${esc(m.name)}</span>`;b.onclick=()=>openRuntime(m.moduleId);nav.insertBefore(b,more);}});
  const mobileSettings=q('#mobileMoreSettings'),grid=mobileSettings&&mobileSettings.parentElement;
  (MS.runtime||[]).forEach(m=>{if(grid&&mobileSettings){const b=document.createElement('button');b.className='ms-mobile-module';b.type='button';b.dataset.moduleId=m.moduleId;b.innerHTML=`<span class='mobileMoreIcon'><b>M</b></span><span><b>${esc(m.name)}</b><small>${esc(m.departmentName||'Custom ONIT module')}</small></span><span class='mobileMoreChevron'>›</span>`;b.onclick=()=>{if(typeof closeMobileMore==='function')closeMobileMore(false);openRuntime(m.moduleId);};grid.insertBefore(b,mobileSettings);}});
}
window.MSUI.fieldType=function(i,type){syncBuilderMeta();const f=MS.editing?.draft?.fields?.[i];if(!f)return;f.type=type;if(type==='select'&&(!f.options||!f.options.length))f.options=['Option 1','Option 2'];renderBuilder();};
window.ONITModuleStudio={refreshRuntime,openRuntime};
try{if(typeof SAFE_RETRY_POST_ACTIONS!=='undefined'){['MODULE_RUNTIME_LIST','MODULE_RUNTIME_GET','MODULE_RECORDS'].forEach(x=>SAFE_RETRY_POST_ACTIONS.add(x));}}catch(_e){}
})();
